    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof sendMessage>>, TError,SendMessageMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof sendMessage>>, TError,SendMessageMutationVariables, TContext> => {

const mutationKey = getSendMessageMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof sendMessage>>, SendMessageMutationVariables> = (props) => {
          const {id,data} = props ?? {};

          return  sendMessage(id,data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type SendMessageMutationResult = NonNullable<Awaited<ReturnType<typeof sendMessage>>>
    export type SendMessageMutationBody = BodyType<MessageInput>
    export type SendMessageMutationError = ErrorType<unknown>
    export type SendMessageMutationVariables = {id: string;data: BodyType<MessageInput>}

    /** @summary Send a message or retry a failed one */
export const useSendMessage = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof sendMessage>>, TError,SendMessageMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof sendMessage>>,
        TError,
        SendMessageMutationVariables,
        TContext
      > => {
      return useMutation(getSendMessageMutationOptions(options), queryClient);
    }

export const getCreateComparisonUrl = () => {




  return `/api/compare`
}

/**
 * @summary Compare live responses across providers
 */
export const createComparison = async (comparisonInput: ComparisonInput, options?: Parameters<typeof customFetch>[1]): Promise<Comparison> => {

  return customFetch<Comparison>(getCreateComparisonUrl(),
  {
    ...options,
    method: 'POST',
    headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
    body: JSON.stringify(comparisonInput)
  }
);}





export const getCreateComparisonMutationKey = () => ['createComparison'] as const;

export const getCreateComparisonMutationOptions = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createComparison>>, TError,CreateComparisonMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
): UseMutationOptions<Awaited<ReturnType<typeof createComparison>>, TError,CreateComparisonMutationVariables, TContext> => {

const mutationKey = getCreateComparisonMutationKey();
const {mutation: mutationOptions, request: requestOptions} = options ?
      options.mutation && 'mutationKey' in options.mutation && options.mutation.mutationKey ?
      options
      : {...options, mutation: {...options.mutation, mutationKey}}
      : {mutation: { mutationKey, }, request: undefined};




      const mutationFn: MutationFunction<Awaited<ReturnType<typeof createComparison>>, CreateComparisonMutationVariables> = (props) => {
          const {data} = props ?? {};

          return  createComparison(data,requestOptions)
        }






  return  { mutationFn, ...mutationOptions }}

    export type CreateComparisonMutationResult = NonNullable<Awaited<ReturnType<typeof createComparison>>>
    export type CreateComparisonMutationBody = BodyType<ComparisonInput>
    export type CreateComparisonMutationError = ErrorType<unknown>
    export type CreateComparisonMutationVariables = {data: BodyType<ComparisonInput>}

    /** @summary Compare live responses across providers */
export const useCreateComparison = <TError = ErrorType<unknown>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof createComparison>>, TError,CreateComparisonMutationVariables, TContext>, request?: SecondParameter<typeof customFetch>}
 , queryClient?: QueryClient): UseMutationResult<
        Awaited<ReturnType<typeof createComparison>>,
        TError,
        CreateComparisonMutationVariables,
        TContext
      > => {
      return useMutation(getCreateComparisonMutationOptions(options), queryClient);
    }

export const getListComparisonsUrl = () => {




  return `/api/comparisons`
}

/**
 * @summary List previous comparisons
 */
export const listComparisons = async ( options?: Parameters<typeof customFetch>[1]): Promise<Comparison[]> => {

  return customFetch<Comparison[]>(getListComparisonsUrl(),
  {
    ...options,
    method: 'GET'


  }
);}





export const getListComparisonsQueryKey = () => {
    return [
    `/api/comparisons`
    ] as const;
    }


export const getListComparisonsQueryOptions = <TData = Awaited<ReturnType<typeof listComparisons>>, TError = ErrorType<unknown>>( options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof listComparisons>>, TError, TData>>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getListComparisonsQueryKey();



    const queryFn: QueryFunction<Awaited<ReturnType<typeof listComparisons>>> = ({ signal }) => listComparisons({ signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listComparisons>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

export type ListComparisonsQueryResult = NonNullable<Awaited<ReturnType<typeof listComparisons>>>
export type ListComparisonsQueryError = ErrorType<unknown>


